const items = $json;
let totalRevenue = 0;
let txCount = 0;
const paymentMethods = {};

for (const item of (Array.isArray(items) ? items : [items])) {
  const amt = Number(item.amount || item.total_amount || 0);
  totalRevenue += amt;
  txCount++;
  const method = item.payment_method || 'UPI';
  paymentMethods[method] = (paymentMethods[method] || 0) + 1;
}

const aov = txCount > 0 ? Math.round((totalRevenue / txCount) * 10) / 10 : 0;

// PRIVACY RULE: Strip all individual transaction IDs, customer names, or phone numbers.
return [{
  json: {
    merchant_id: $('Trigger: Supabase Integration Dispatcher').first().json.body.merchant_id || 'm-001',
    aggregated_summary: {
      total_revenue: Math.round(totalRevenue * 100) / 100,
      total_transactions: txCount,
      average_order_value: aov,
      payment_method_distribution: paymentMethods
    },
    pii_sanitized: true,
    data_safe_for_ml: true
  }
}];

const merchant = $('2a. Supabase Read: Merchant Metadata').first().json[0] || {};
const segments = $('2b. Supabase Read: Customer Segments').all().map(i => i.json);

// PRIVACY RULE: Ensure no customer names or contacts are present in AI input
return [{
  json: {
    merchant_id: merchant.id || 'm-001',
    merchant_name: merchant.name || 'Sharma Tea Corner',
    business_category: merchant.business_category || 'Food & Beverage',
    monthly_revenue: merchant.monthly_revenue || 284500.0,
    cohort_breakdown: segments,
    pii_sanitized: true,
    ready_for_ai_analysis: true
  }
}];
